select set_config('request.jwt.claims','{"iss":"https://admin-owner.invalid","sub":"user_aaaaaaaaaaaaaaaaaaaaaaaaaaa","role":"authenticated","sid":"sess_fixture","azp":"https://app.invalid"}',true);
select lives_ok($$select public.testing_contribution_review('19100400-0000-4000-8000-000000000008','declined','Synthetic review','{"schema":"vantare.triage.v2","verdict":"dudoso","criteria":{"contenido_minimo":"si","evidencia":"debil","no_duplicado":"si"},"duplicate_of":null,"severity":"baja","area":"testing-center","evidence_refs":[],"summary":"Synthetic","preliminary_fix":null,"confidence":0.5,"reasons":[],"trazable":"si"}'::jsonb)$$,'operational owner without membership can review');
