select ok(not has_function_privilege('anon','public.testing_contribution_review(uuid,text,text,jsonb)','execute'),'anon review remains closed');
select ok(not has_function_privilege('service_role','public.testing_contribution_review(uuid,text,text,jsonb)','execute'),'service review remains closed');
select is((select count(*)::integer from public.testing_center_memberships where role='owner' and actor_id like 'fixture-owner-%'),4,'authorization never rewrites membership');
select * from finish();
rollback;
